function fourSumGroups(nums: number[], target: number): number[][] {
  const n = nums.length, seen = new Map<string, number[]>();
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      for (let c = b + 1; c < n; c++)
        for (let d = c + 1; d < n; d++) {
          if (nums[a] + nums[b] + nums[c] + nums[d] !== target) continue;
          const g = [nums[a], nums[b], nums[c], nums[d]].sort((x, y) => x - y);
          seen.set(g.join(","), g);
        }
  return [...seen.values()];
}

