function fourSumGroups(nums: number[], target: number): number[][] {
  nums.sort((x, y) => x - y);
  const n = nums.length, out: number[][] = [];
  for (let i = 0; i < n - 3; i++) {
    if (i > 0 && nums[i] === nums[i - 1]) continue;
    for (let j = i + 1; j < n - 2; j++) {
      if (j > i + 1 && nums[j] === nums[j - 1]) continue;
      let lo = j + 1, hi = n - 1;
      while (lo < hi) {
        const s = nums[i] + nums[j] + nums[lo] + nums[hi];
        if (s < target) lo++;
        else if (s > target) hi--;
        else {
          out.push([nums[i], nums[j], nums[lo], nums[hi]]);
          while (lo < hi && nums[lo] === nums[lo + 1]) lo++;
          while (lo < hi && nums[hi] === nums[hi - 1]) hi--;
          lo++;
          hi--;
        }
      }
    }
  }
  return out;
}

